"""Standard-interface bookshelf control and complete action record.
No reset, state access, or simulator access; geometry comes from Robot.spec().
Run with --replay only on a fresh authorized episode to execute recorded actions.
"""
import json,sys
from pathlib import Path
import numpy as np
from rcb_client import Robot
OUT=Path('/app/output'); OUT.mkdir(exist_ok=True)
r=Robot(); spec=r.spec()
(OUT/'spec.json').write_text(json.dumps(spec,indent=2))
names=spec['action_types']['joint_position']['layout']
ranges=np.array(spec['action_types']['joint_position']['range_rad'])
joints=spec['proprio']['joints']
def from_obs(obs):
 p=dict(zip(spec['proprio_layout'],obs.meta['proprio']['now']))
 q=[]
 for n in names:
  n=n.replace('_A_','_')
  q.append(p[n+'_pos'] if not n.endswith('J0') else p[n[:-1]+'1_pos']+p[n[:-1]+'2_pos'])
 return np.array(q)
def norm(q): return np.clip(2*(np.array(q)-ranges[:,0])/(ranges[:,1]-ranges[:,0])-1,-1,1)
def observation(tag='current'):
 o=r.get_obs();o.save(OUT/tag)
 return o
def move(q,steps=10,tag='move',ramp=True):
 o=r.get_obs(cameras=[]); start=from_obs(o)
 a=np.array([norm(start+(np.asarray(q)-start)*(i+1)/steps) for i in range(steps)]) if ramp else np.tile(norm(q),(steps,1))
 with (OUT/'actions.jsonl').open('a') as f:f.write(json.dumps({'tag':tag,'actions':a.tolist()})+'\n')
 z=r.submit('joint_position',a,cameras=None,video='frames',video_fps=25,note=tag)
 z.save(OUT/tag);z.save(OUT/'current')
 np.save(OUT/'target.npy',q)
 p=dict(zip(spec['proprio_layout'],z.meta['proprio']['now']))
 print(json.dumps({k:z.meta.get(k) for k in ['control_steps','done','reason']}))
 print('IMU', {k:round(v,4) for k,v in p.items() if k.startswith('imu_')})
 return z
if __name__=='__main__':
 if '--replay' in sys.argv:
  for line in (OUT/'actions.jsonl').read_text().splitlines():
   chunk=json.loads(line);z=r.submit('joint_position',chunk['actions'],note=chunk['tag'])
   if z.done:break
 else: print(r.status())
