import json,numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
S=json.load(open('/app/output/spec.json')); J=S['proprio']['joints']; L=S['links']['names']; P=S['links']['parent']
axes=np.array(S['proprio']['axis']);pos=np.array(S['proprio']['position_m'])
def rot(axis,q):return Rotation.from_rotvec(np.array(axis)*q).as_matrix()
def transforms(q):
 T={'pelvis':np.eye(4)}
 for i,n in enumerate(L[1:]):
  R=rot(axes[i],q[i]);H=np.eye(4);H[:3,:3]=R;H[:3,3]=pos[i]-R@pos[i];T[n]=T[P[i+1]]@H
 return T
def point(T,link,p):return (T[link]@np.r_[p,1])[:3]
def actuator_to_joint(q):
 names=S['action_types']['joint_position']['layout'];d={n.replace('_A_','_'):v for n,v in zip(names,q)}
 return np.array([d[n] if n in d else d[n[:-1]+'0']/2 for n in J])
def fk(q):return transforms(actuator_to_joint(q))
def palm(q,side='right'):
 T=fk(q);pre='rh' if side=='right' else 'lh';return point(T,pre+'_palm',[.43,-.214 if side=='right' else .214,.087])
def ik(q,target,side='right',direction=None):
 ids=[16,17,18,19,20,41,42] if side=='right' else [11,12,13,14,15,21,22]
 ranges=np.array(S['action_types']['joint_position']['range_rad']);q=np.array(q).copy();seed=q[ids].copy()
 def fun(x):
  qq=q.copy();qq[ids]=x; T=fk(qq);pre='rh' if side=='right' else 'lh';t=T[pre+'_palm'];p=point(T,pre+'_palm',[.43,-.214 if side=='right' else .214,.087]);e=list((p-target)*10)
  if direction is not None: e+=list((t[:3,:3]@np.array([1,0,0])-direction)*2)
  e+=list((x-seed)*.03)
  return e
 opt=least_squares(fun,seed,bounds=(ranges[ids,0]+.0001,ranges[ids,1]-.0001),max_nfev=200)
 q[ids]=opt.x;print('IK',palm(q,side),'angles',q[ids], 'cost',opt.cost);return q
if __name__=='__main__':
 q=np.zeros(61);q[[2,7]]=-.4;q[[3,8]]=.8;q[[4,9]]=-.4
 print('palms',palm(q),palm(q,'left'))
 T=fk(q);m=np.array(S['links']['mass_kg']);p=np.array([point(T,n,c) for n,c in zip(L,S['links']['com_m'])]);print('COM',m@p/m.sum())
